document.addEventListener("DOMContentLoaded", function () {
  const citeElements = document.querySelectorAll("cite[data-ref]");
  const bibContainer = document.getElementById("bibliography");
  const citedOrder = [];
  const citedMap = {};

  citeElements.forEach((el) => {
    const key = el.getAttribute("data-ref").trim();
    if (!key) return;

    if (!(key in citedMap)) {
      citedOrder.push(key);
      citedMap[key] = citedOrder.length;
    }
    const num = citedMap[key];
    el.innerHTML = `<a href="#ref-${key}">[${num}]</a>`;
  });

  if (bibContainer) {
    const keysToRender = citedOrder.length > 0 ? citedOrder : Object.keys(BIBLIOGRAPHY_DATA);
    const listHtml = keysToRender.map((key, idx) => {
      const item = BIBLIOGRAPHY_DATA[key];
      const num = citedMap[key] || (idx + 1);
      if (!item) {
        return `<p id="ref-${key}">[${num}] <em>Missing reference: ${key}</em></p>`;
      }
      const author = item.author ? `${item.author}. ` : "";
      const title = item.title ? `"${item.title}." ` : "";
      const venue = item.journal || item.booktitle || item.publisher || "";
      const venueStr = venue ? `<em>${venue}</em>, ` : "";
      const year = item.year ? `${item.year}.` : "";
      const url = item.url ? ` <a href="${item.url}" target="_blank">[Link]</a>` : "";

      return `<p id="ref-${key}">[${num}] ${author}${title}${venueStr}${year}${url}</p>`;
    }).join("\n");

    bibContainer.innerHTML = listHtml;
  }
});
